dtsPropsFor.Card:
/** Heading rendered as an <h2> above the content. Omit for an untitled card. */
title?: React.ReactNode;
/** Card body. */
children?: React.ReactNode;

dtsPropsFor.FormInput:
/** Visible <label> text for the field. */
label: React.ReactNode;
/** Validation message. When set the input gets aria-invalid and the message is announced with role="alert". */
error?: React.ReactNode;
/** Marks the field required and appends a decorative asterisk to the label. */
required?: boolean;
/** Input id. Defaults to `name` — this is what ties the label and the error message to the input. */
id?: string;
/** Field name; doubles as the fallback id. */
name?: string;
/** Input type (text, email, password, date, number, ...). */
type?: string;
value?: string | number;
defaultValue?: string | number;
onChange?: React.ChangeEventHandler<HTMLInputElement>;
placeholder?: string;
disabled?: boolean;
autoComplete?: string;
/** Every other prop is forwarded verbatim to the underlying <input>. */
[key: string]: unknown;

dtsPropsFor.FeedbackRegion:
/** Error message, rendered in the error style with role="alert". Takes precedence over `success`. */
error?: React.ReactNode;
/** Success message, rendered in the success style and announced politely. */
success?: React.ReactNode;

dtsPropsFor.EmptyState:
/** Headline. Defaults to "Nenhum resultado encontrado.". */
title?: React.ReactNode;
/** Optional supporting line under the headline. */
description?: React.ReactNode;

dtsPropsFor.ErrorState:
/** Error message to display. */
message?: React.ReactNode;
/** When provided, renders a "Tentar novamente" button that calls this handler. */
onRetry?: () => void;

dtsPropsFor.RequestState:
/** Show the loading state. Checked first. */
loading?: boolean;
/** Error message. Renders ForbiddenState when `forbidden` is also set, otherwise ErrorState. */
error?: string;
/** Show the empty state. Checked after loading, forbidden and error. */
empty?: boolean;
/** Render the forbidden state instead of the generic error. */
forbidden?: boolean;
/** Retry handler forwarded to ErrorState. */
onRetry?: () => void;
/** Rendered when none of the state flags apply. */
children?: React.ReactNode;
